code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Color 4 lines divide the canvas into compartments.
    row_bands = []
    start = 0
    for r in range(h):
        if all(v == 4 for v in grid[r]):
            if start < r:
                row_bands.append((start, r))
            start = r + 1
    if start < h:
        row_bands.append((start, h))
    col_bands = []
    start = 0
    for c in range(w):
        if all(grid[r][c] == 4 for r in range(h)):
            if start < c:
                col_bands.append((start, c))
            start = c + 1
    if start < w:
        col_bands.append((start, w))
    out = [row[:] for row in grid]
    source = None
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            if any(grid[r][c] not in (4, 9) for r in range(r0, r1) for c in range(c0, c1)):
                source = (r0, r1, c0, c1)
                break
        if source:
            break
    if source is None:
        return out
    r0, r1, c0, c1 = source
    pattern = [row[c0:c1] for row in grid[r0:r1]]
    for a, b in row_bands:
        for x, y in col_bands:
            if b-a == len(pattern) and y-x == len(pattern[0]):
                for dr in range(b-a):
                    out[a+dr][x:y] = pattern[dr][:]
    return out
